#!/usr/bin/env node
// Hook: UserPromptSubmit
// 1) Chặn prompt có chứa thứ trông giống secret (API key, token, mật khẩu) trước khi gửi cho model.
// 2) Với prompt hợp lệ: bổ sung ngữ cảnh (nhánh git hiện tại) vào cuộc hội thoại.

import { execSync } from "node:child_process";

const SECRET_PATTERNS = [
  /sk-[A-Za-z0-9_-]{20,}/, // OpenAI / Anthropic style key
  /ghp_[A-Za-z0-9]{30,}/, // GitHub token
  /AKIA[0-9A-Z]{16}/, // AWS access key
  /(password|mat_?khau|secret)\s*[:=]\s*\S{6,}/i,
];

const input = JSON.parse(await readStdin());
const prompt = input.prompt ?? "";

if (SECRET_PATTERNS.some((pattern) => pattern.test(prompt))) {
  console.log(
    JSON.stringify({
      decision: "block",
      reason:
        "🔐 scan-prompt: prompt có vẻ chứa secret (API key/token/mật khẩu). " +
        "Hãy xóa secret và dùng biến môi trường thay thế.",
    }),
  );
  process.exit(0);
}

let branch = "unknown";
try {
  branch = execSync("git branch --show-current", {
    cwd: process.env.CLAUDE_PROJECT_DIR ?? input.cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
  }).trim();
} catch {
  // không phải git repo
}

console.log(
  JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: `Nhánh git hiện tại: ${branch}. Nhớ chạy "npm run check" trước khi báo hoàn thành.`,
    },
  }),
);

process.exit(0);

async function readStdin() {
  let data = "";
  for await (const chunk of process.stdin) data += chunk;
  return data || "{}";
}

#!/usr/bin/env node
// Hook: PreToolUse (matcher: Edit|Write)
// Chặn agent sửa các file nhạy cảm. Cách chặn: in lý do ra stderr và thoát với exit code 2
// -> Claude Code hủy thao tác và gửi lý do cho agent để nó đổi cách làm.

import path from "node:path";

const PROTECTED = [
  { pattern: /(^|\/)\.env(\..*)?$/, reason: "file biến môi trường có thể chứa bí mật" },
  { pattern: /(^|\/)package-lock\.json$/, reason: "chỉ được thay đổi qua lệnh npm install" },
  { pattern: /^storage\//, reason: "dữ liệu đơn hàng thật, không sửa bằng tay" },
  { pattern: /^\.git\//, reason: "không được sửa nội bộ git" },
];

const input = JSON.parse(await readStdin());
const filePath = input.tool_input?.file_path;
if (!filePath) process.exit(0);

const projectDir = process.env.CLAUDE_PROJECT_DIR ?? input.cwd;
const relativePath = path.relative(projectDir, filePath).split(path.sep).join("/");

for (const { pattern, reason } of PROTECTED) {
  if (pattern.test(relativePath)) {
    console.error(
      `⛔ Hook protect-files: không được sửa "${relativePath}" (${reason}). ` +
        `Hãy dừng lại và hỏi người dùng nếu thật sự cần thay đổi file này.`,
    );
    process.exit(2);
  }
}

process.exit(0);

async function readStdin() {
  let data = "";
  for await (const chunk of process.stdin) data += chunk;
  return data || "{}";
}
